function computeTC(scenario, x1, x2, y, z) {
  const [p1, p2, pf, c1, d1, c2, d2, a, df, s, L, r] = scenario;
  const pi1 = x1 ? 0 : p1;
  const pi2 = x2 ? 0 : p2;
  const q = 1 - (1-pi1)*(1-pi2)*(1-pf);
  const C1 = x1 ? (c1+d1)/(1-p1) : c1;
  const C2 = x2 ? (c2+d2)/(1-p2) : c2;
  const Casm = C1 + C2 + a;
  const nf = 1/(1-q);
