  let newCost1, newCost2;
  const recycled = q/(1-q); // number of recycled sets
  if (x1) {
    const needed = nf - recycled*(1-p1);
    newCost1 = (c1+d1) * (needed/(1-p1)) + d1*recycled;
  } else {
    newCost1 = c1 * (nf - recycled);
  }
  if (x2) {
    const needed = nf - recycled*(1-p2);
    newCost2 = (c2+d2) * (needed/(1-p2)) + d2*recycled;
  } else {
    newCost2 = c2 * (nf - recycled);
  }
  const TC = newCost1 + newCost2 + a*nf + df*y*nf + L*(1-y)*recycled + r*z*recycled;
