// We'll compute expected TC over posterior using Monte Carlo (10000 samples)
function sampleBeta(alpha, beta) {
  // Marsaglia & Tsang method
  if (alpha < 1 || beta < 1) {
    // use simple rejection for small alpha/beta
    let u1, u2;
    do {
      u1 = Math.random();
      u2 = Math.random();
    } while (u1 + u2 > 1);
    return u1/(u1+u2);
  }
  const a = alpha, b = beta;
  const theta = (a + b - 2) / (2*a*b - a - b);
  const lambda = 4*a*b - 2*(a+b) - 4;
  const c = (a + 1) / (2*b - 1);
  let u, v, w;
  do {
    u = Math.random();
    v = Math.random();
    w = u * (1 - u);
    if (lambda * w < 1) {
      if (lambda * w < 1 - 2*theta*u + theta*theta) {
        return c * v / (c*u + 1 - u);
      }
    }
  } while (true);
}

